import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const sharedDir = path.dirname(fileURLToPath(import.meta.url));
const scenarioDir = path.dirname(sharedDir);
const sourcePath = path.join(sharedDir, "terminal-keymap.json");
const outputPath = path.join(scenarioDir, "api/handlers/terminal/keymap_generated.go");

const entries = JSON.parse(await readFile(sourcePath, "utf8"));
const lines = [
  "// Code generated by shared/generate-terminal-keymap.mjs; DO NOT EDIT.",
  "",
  "package terminal",
  "",
  "var defaultKeyBytes = map[string][]byte{",
  ...entries.map(({ name, bytes }) => `\t${JSON.stringify(name)}: {${bytes.map((byte) => `0x${byte.toString(16).padStart(2, "0")}`).join(", ")}},`),
  "}",
  "",
];

await writeFile(outputPath, lines.join("\n"));
